//! Pascal's *ordinal* types: those whose values can be counted (integers,
//! `Char`, `Boolean` and enumerations). Only ordinals can index arrays and
//! strings, so the runtime's `Index` impls accept any `T: Ordinal`.

pub trait Ordinal: Copy {
    /// Pascal `Ord(x)`: the value's position, as a wide integer.
    fn ord(self) -> i64;
}

// One impl per integer type, generated by a small macro.
macro_rules! impl_ordinal {
    ($($t:ty),*) => {
        $( impl Ordinal for $t { fn ord(self) -> i64 { self as i64 } } )*
    };
}
impl_ordinal!(i8, i16, i32, i64, u8, u16, u32);

impl Ordinal for bool {
    fn ord(self) -> i64 {
        self as i64
    }
}
